function featureVector(f){const lat=f.lat*Math.PI/180,lon=f.lon*Math.PI/180;return new T.Vector3(Math.cos(lat)*Math.cos(lon),Math.sin(lat),-Math.cos(lat)*Math.sin(lon))}
